from lib import *
recs=[]
recs.append(R(7153228,"ٹوفو بھرے ہوئے کھمبے","کھیت کے کھمبے پالک اور ہری پیاز سے بھرے ہوئے، اوپر تاہینی اور ٹوفو ڈال کر روسٹ کیے گئے۔","2","278 گرام",
["2 بڑے پورٹوبیلو کھمبے، ڈنٹھل نکال کر محفوظ رکھے ہوئے","1 چائے کا چمچ ریپ سیڈ کا تیل","3 ہری پیاز، باریک کٹی ہوئی","150 گرام سخت ٹوفو، باریک کٹا ہوا","100 گرام منجمد پالک، پگھلائی ہوئی اور پانی نچوڑا ہوا","اچھی خاصی چٹکی کالی مرچ","2 چائے کے چمچ تاہینی","1 چائے کا چمچ ڈیژون رائی","1 کھانے کا چمچ تازہ تلسی، کٹی ہوئی","6 چیری ٹماٹر، کٹے ہوئے"],
["اوون کو 180°C / گیس مارک 4 پر پہلے سے گرم کریں۔ کھمبوں کے ڈھکن (اوپر کا حصہ نیچے کی طرف) ہلکا تیل لگی بیکنگ شیٹ پر رکھیں۔","بڑے پین میں درمیانی آنچ پر تیل گرم کریں، پھر کھمبوں کے ڈنٹھل باریک کاٹ کر ہری پیاز اور ٹوفو کے ساتھ پین میں ڈال دیں۔","3-4 منٹ پکائیں، پھر پالک اور مرچ ڈالیں اور بار بار ہلاتے ہوئے 2-3 منٹ پکائیں۔","آنچ سے اتار لیں اور تاہینی، رائی اور تلسی ملا دیں۔","ہر کھمبے پر ٹوفو کا آمیزہ ڈھیر کی صورت میں رکھیں اور 15-20 منٹ بیک کریں۔ اوپر کٹے ہوئے ٹماٹر ڈال کر پیش کریں۔"],
["آپ ہری پیاز کی جگہ لیک اور تلسی کی جگہ اجمود استعمال کر سکتے ہیں۔","چٹکی بھر مرچ کے فلیکس یا ایک چائے کا چمچ اسموکڈ پپریکا ڈال کر اسے مزید مسالے دار بنائیں۔","کھمبوں کی جگہ آدھی کٹی ہوئی شملہ مرچیں بھی بھری جا سکتی ہیں۔","منجمد کرنے کی ہدایات: پکانے کے بعد کھمبے منجمد کرنے کے لیے موزوں ہیں۔ کٹے ہوئے ٹماٹروں کے بغیر، ہر ایک کو الگ سے چکنائی روک کاغذ میں لپیٹیں۔ 2 گھنٹے پگھلائیں، پھر مائیکرو ویو یا معتدل اوون میں گرم کریں۔",FVH(2)],[]))
recs.append(R(7156026,"گرمیوں کے بیریز کا پاولووا","کسی بھی موقع کے لیے ایک شاندار میٹھا، چکنائی اور چینی میں کم، اور بیریز کی خوبیوں سے بھرپور۔","5","177 گرام",
["½ ڈبہ تازہ اسٹرابیریاں (160 گرام)","چھوٹی ٹوکری تازہ رسبھریاں (120 گرام)","چھوٹی ٹوکری تازہ بلیو بیریز (120 گرام)","4 کھانے کے چمچ پانی","3.5 کھانے کے چمچ دانے دار سویٹنر","1 چائے کا چمچ لیموں کا رس","6 انڈوں کی سفیدی","1 چائے کا چمچ کریم آف ٹارٹر","4 چائے کے چمچ کارن فلور","200 گرام 0% چکنائی والا یونانی دہی","سویٹنر، ذائقے کے مطابق","پیش کرنے کے لیے پودینے کی چند ٹہنیاں"],
["پانی، دانے دار سویٹنر اور لیموں کا رس چھوٹے پین میں دھیمی آنچ پر رکھیں یہاں تک کہ مائع کم ہو کر چپچپا نظر آنے لگے۔","اسی دوران انڈوں کی سفیدی اور کریم آف ٹارٹر پیالے میں ڈالیں اور آہستہ آہستہ پھینٹیں یہاں تک کہ نرم چوٹیاں بننے لگیں۔","سویٹنر کا آمیزہ آہستہ آہستہ پھینٹی ہوئی انڈوں کی سفیدی میں ڈالیں۔","نرمی سے کارن فلور ڈالیں اور ملاتے رہیں یہاں تک کہ انڈوں کی سفیدی سخت ہو جائے۔","پارچمنٹ بچھی بیکنگ ٹرے پر میرینگ کو پھیلائیں یا پائپ کریں تاکہ تقریباً 20-25 سینٹی میٹر (10 انچ) چوڑا پیالہ بن جائے۔","ٹھنڈے اوون میں، 100°C/گیس ¼ پر تقریباً 1 گھنٹہ 20 منٹ بیک کریں، یہاں تک کہ وہ سخت ہو جائے اور رنگ بدلنا شروع ہو۔ اوون کا دروازہ کھول دیں اور میرینگ کو اوون ہی میں ٹھنڈا ہونے دیں۔","ٹھنڈا ہونے پر میرینگ کو احتیاط سے پیش کرنے والی پلیٹ پر رکھیں۔","ایک تہائی پھل کو دہی میں ملائیں، ضرورت ہو تو سویٹنر ڈالیں۔ اسے میرینگ میں ڈھیر کر دیں اور اوپر باقی بیریز اور پودینے کی چند ٹہنیاں سجا دیں۔"],
["اگر آپ کی میرینگ پکنے سے پہلے بھوری ہونے لگے تو چند منٹ کے لیے اوون کا دروازہ کھول دیں تاکہ حرارت کم ہو جائے۔","میرینگ کو پیش کرنے سے ذرا پہلے ہی بھریں، ورنہ بیریز کی بھرائی کے ساتھ زیادہ دیر رہنے سے وہ گیلی ہو جائے گی۔ البتہ آپ دہی/پھل کا آمیزہ پہلے سے بنا کر ضرورت تک فریج میں رکھ سکتے ہیں۔",FVH(1)],[]))
recs.append(R(7157427,"ٹماٹر کی چٹنی میں کاڈ مچھلی","کم چکنائی والی ڈش، چاول اور سلاد کے ساتھ مزیدار لگتی ہے۔","2","441 گرام",
["1 کھانے کا چمچ زیتون کا تیل","1 بڑی پیاز، چھلی اور کٹی ہوئی","400 گرام ڈبہ کٹے ہوئے ٹماٹر","1 کھانے کا چمچ ٹماٹر کیچپ","2 تیز پات","1 ڈھیر والا چائے کا چمچ خشک اجمود یا 1 کھانے کا چمچ تازہ کٹا ہوا اجمود","تازہ پسی ہوئی کالی مرچ","2 موٹے ٹکڑے بغیر چھلکے کاڈ فلے (تقریباً 150 گرام ہر ایک)"],
["نان اسٹک فرائنگ پین میں تیل گرم کریں۔","پیاز ڈالیں اور 5 منٹ بھونیں یہاں تک کہ نرم ہو جائے۔","باقی تمام اجزاء (کاڈ کے علاوہ) ڈالیں، کالی مرچ چھڑکیں، ابال آنے دیں، بغیر ڈھانپے دھیمی آنچ پر 15 منٹ پکائیں۔","کاڈ کو چٹنی کے اوپر رکھیں، ڈھانپ دیں اور مزید 15 منٹ پکاتے رہیں یہاں تک کہ مچھلی پک جائے۔ تیز پات نکال دیں۔"],
["یہ ترکیب سالمن، تازہ ٹیونا یا ہیڈاک کے ساتھ بھی اچھی بنتی ہے۔","ڈش کو مسالے دار بنانے کے لیے ٹماٹر کی چٹنی میں 2 جوے کُوٹا ہوا لہسن اور 1 چائے کا چمچ اسموکڈ پپریکا ڈال دیں۔","منجمد کرنے کی ہدایات: پکانے کے بعد منجمد کرنے کے لیے موزوں ہے۔ فریج میں پگھلائیں اور اندر تک بھاپ نکلنے لگے تک گرم کریں۔",FVH(3)],[]))
recs.append(R(7157800,"کینوا بھرا ہوا بٹرنٹ اسکوائش","بٹرنٹ اسکوائش کو کینوا، بیجوں اور سبزیوں سے بھر دیا جائے تو یہ مکمل کھانا بن جاتا ہے۔","2","414 گرام",
["1 چھوٹا بٹرنٹ اسکوائش، بیج نکالا ہوا (500 گرام)","70 گرام کینوا","150 ملی لیٹر ابلتا پانی","1 چائے کا چمچ ریپ سیڈ کا تیل","1 پیاز، باریک کٹی ہوئی","آدھی لال شملہ مرچ، باریک کٹی ہوئی","1 ڈھیر والا چائے کا چمچ زیرہ","3 جوے لہسن، کُوٹے ہوئے","چٹکی بھر مرچ کے فلیکس","1 کھانے کا چمچ کدو کے بیج","6 چیری ٹماٹر، آدھے کٹے ہوئے","6 ٹہنیاں تازہ روزمیری"],
["اوون کو 180°C/گیس 4 پر پہلے سے گرم کریں۔ اسکوائش کو لمبائی میں آدھا کاٹیں، بیج نکال دیں اور 35-40 منٹ بیک کریں یہاں تک کہ نرم ہو جائے۔","اسی دوران کینوا کو ابلتے پانی کے پین میں ڈالیں، ابال آنے دیں اور آنچ کم کر دیں۔ ڈھانپ دیں اور دھیمی آنچ پر 10-15 منٹ پکائیں۔","دوسرے پین میں تیل ڈالیں اور پیاز اور شملہ مرچ 5 منٹ پکائیں۔ زیرہ، لہسن اور مرچ کے فلیکس ڈالیں اور مزید 2 منٹ پکائیں۔","کینوا کا فالتو پانی نکال دیں اور اسے پیاز کے آمیزے میں ہلا کر ملا دیں۔ کدو کے بیج ڈالیں اور اچھی طرح ملائیں۔","کینوا کو اسکوائش پر ڈھیر کر دیں، اوپر ٹماٹر رکھیں اور مزید 10 منٹ بیک کریں۔ روزمیری کی ٹہنیوں کے ساتھ پیش کریں۔"],
["بھرائی کے لیے کینوا کی جگہ کس کس یا دلیہ (بلگر گندم) استعمال کر سکتے ہیں۔","مختلف مسالے، جیسے کری پیسٹ، یا تازہ جڑی بوٹیاں، جیسے دھنیا یا ٹیرگن آزما کر دیکھیں۔","اگر چاہیں تو اوپر تھوڑا کم چکنائی والا پنیر ڈالیں۔","منجمد کرنے کی ہدایات: پکانے کے بعد منجمد کرنے کے لیے موزوں ہے۔ فریج یا مائیکرو ویو میں پگھلائیں اور اوون یا مائیکرو ویو میں اندر تک بھاپ نکلنے لگے تک دوبارہ گرم کریں۔",FVH(4)],[]))
recs.append(R(7160544,"ہری گرمیوں کا سوپ","جڑی بوٹیوں، سبزیوں اور فلاجیولیٹ پھلیوں سے بھرپور ایک تروتازہ اور شاندار ہرا گرمیوں کا سوپ۔","4","340 گرام",
["2 چائے کے چمچ ریپ سیڈ کا تیل","250 گرام ایسپیریگس کا گچھا، موٹا کٹا ہوا اور سخت ڈنٹھل نکالے ہوئے","2 جوے لہسن، کُوٹے ہوئے","1 گچھا ہری پیاز، صاف کر کے کٹی ہوئی","1 ڈبہ 400 گرام فلاجیولیٹ پھلیاں، پانی نکالی ہوئی (پانی نکالنے کے بعد 265 گرام)","1 کم نمک والا سبزیوں کا اسٹاک کیوب 500 ملی لیٹر ابلتے پانی میں","اچھی خاصی چٹکی سفید مرچ","200 گرام تازہ پالک کا پیکٹ","160 گرام کھیرا، کٹا ہوا","مٹھی بھر (25 گرام) ملی جلی تازہ جڑی بوٹیاں، جیسے اجمود اور تلسی","1 x 150 گرام ایوکاڈو، چھلا ہوا اور گٹھلی نکالی ہوئی","3 کھانے کے چمچ 0% چکنائی والا یونانی طرز کا دہی","4 قتلے کھیرا، کٹا ہوا","3 مولیاں، کٹی ہوئی اور قیمہ کی ہوئی"],
["پین میں تیل ڈالیں، ایسپیریگس ڈالیں اور 3 منٹ پکائیں۔ لہسن ڈالیں اور بار بار ہلاتے ہوئے مزید 2 منٹ پکائیں۔","ہری پیاز، فلاجیولیٹ پھلیاں، اسٹاک اور سفید مرچ ڈالیں اور ابال آنے دیں۔ آنچ کم کریں، ڈھانپ دیں اور 6-8 منٹ دھیمی آنچ پر پکائیں یہاں تک کہ ایسپیریگس نرم ہو جائے۔","پالک اور کھیرا ڈالیں، دوبارہ ابال لائیں، پھر آنچ سے اتار لیں۔","اسے مکمل طور پر ٹھنڈا ہونے دیں، پھر فریج میں ٹھنڈا کریں۔ پیش کرنے سے ذرا پہلے جڑی بوٹیاں، ایوکاڈو اور دہی ڈالیں، پھر ہموار ہونے تک بلینڈ کریں۔","پیالوں میں ڈالیں اور کٹے ہوئے کھیرے اور مولی سے سجائیں۔"],
["مختلف جڑی بوٹیوں، جیسے پودینہ یا دھنیا، کے ساتھ تجربہ کریں۔ ایک دوسرے سے میل کھانے والی جڑی بوٹیوں کے امتزاج کے ساتھ سب سے بہتر بنتا ہے۔","پالک کی جگہ لیٹس یا واٹر کریس استعمال کر کے دیکھیں۔","منجمد کرنے کی ہدایات: جڑی بوٹیاں، ایوکاڈو اور دہی ڈالنے سے پہلے منجمد کرنے کے لیے موزوں ہے۔ فریج میں پگھلائیں، پھر جڑی بوٹیاں، ایوکاڈو اور دہی ڈال کر بلینڈ کریں۔",FVH(3)],[]))
recs.append(R(7161543,"لیمب دھنسک","بھیڑ کے گوشت، سبزیوں اور دال سے بنا درمیانے مسالے کا سالن، گاڑھی اور لذیذ گریوی میں۔","4","421 گرام",
["2 چائے کے چمچ ریپ سیڈ کا تیل","1 پیاز، کٹی ہوئی","350 گرام بھیڑ کی ران کے چوکور ٹکڑے","2 گاجریں، کٹی ہوئی","4 جوے لہسن، کُوٹے ہوئے","3 سینٹی میٹر تازہ ادرک کی جڑ، کدوکش کی ہوئی","100 گرام مسور کی دال","1 کم نمک والا بھیڑ یا مرغی کا اسٹاک کیوب 400 ملی لیٹر ابلتے پانی میں","1 x 400 گرام ڈبہ کٹے ہوئے ٹماٹر","1 کھانے کا چمچ ہلکا کری پیسٹ","1-2 شکر قندی (400 گرام)، چھلی اور کٹی ہوئی","1 بینگن، کٹا ہوا","20 گرام تازہ دھنیا، موٹا کٹا ہوا"],
["پین میں تیل ڈالیں، پھر پیاز ڈال کر 3-4 منٹ پکائیں یہاں تک کہ بھورا ہونے لگے۔","بھیڑ کا گوشت ڈالیں اور مزید 4-5 منٹ پکائیں، یہاں تک کہ اچھی طرح بھور جائے۔ گاجر، لہسن اور ادرک ڈالیں اور بار بار ہلاتے ہوئے مزید 2-3 منٹ پکائیں۔","دال، اسٹاک، ٹماٹر اور کری پیسٹ ڈالیں اور اچھی طرح ملائیں۔ ابال آنے دیں، ڈھکن لگا دیں، آنچ کم کریں، پھر 1 گھنٹہ دھیمی آنچ پر پکائیں۔","شکر قندی اور بینگن ڈالیں، ملائیں اور دوبارہ ڈھانپ دیں۔ مزید 20 منٹ دھیمی آنچ پر پکائیں۔","دیکھیں کہ گوشت نرم ہو گیا ہے۔ اگر نہیں، تو مزید 10-15 منٹ پکائیں۔ تازہ دھنیا ملا دیں، تھوڑا سا اوپر ڈالنے کے لیے بچا لیں، اور پیش کریں۔"],
["آپ یہ ڈش کسی بھی کم چکنائی والے گوشت، جیسے بڑے کا گوشت یا سور کا گوشت، سے بنا سکتے ہیں۔","جلدی تیار ہونے والے ورژن کے لیے، چوکور کٹا ہوا مرغی یا ٹرکی کا گوشت استعمال کریں اور شکر قندی اور بینگن ڈالنے سے پہلے 1 گھنٹے کی بجائے 15 منٹ پکائیں۔","منجمد کرنے کی ہدایات: پکانے کے بعد منجمد کرنے کے لیے موزوں ہے۔ فریج یا مائیکرو ویو میں پگھلائیں اور اندر تک بھاپ نکلنے لگے تک گرم کریں۔",FVH(4)],[]))
recs.append(R(7161660,"برسلز اور ہیش پچے ہوئے انڈے کے ساتھ","ایک تسلی بخش ڈش جو خاندان کی شام کی چائے یا بھرپور ناشتے کے لیے بہترین ہے۔","4","362 گرام",
["200 گرام آلو","300 گرام شکر قندی","500 گرام برسلز اسپراؤٹس، صاف کیے ہوئے","بڑی چٹکی سفید مرچ","2 چائے کے چمچ زیتون کا تیل","1 بڑی پیاز، باریک کٹی ہوئی","4 انڈے، پچائے ہوئے (پوچ کیے ہوئے)"],
["آلو اور شکر قندی کو رگڑ کر دھوئیں اور کوئی داغ ہو تو نکال دیں، لیکن چھلکا نہ اتاریں۔ بڑے ٹکڑوں میں کاٹیں اور ابلتے پانی سے ڈھانپ دیں۔ 10–12 منٹ دھیمی آنچ پر پکائیں۔","برسلز اسپراؤٹس ڈالیں اور ڈھکن دوبارہ لگا دیں۔ 7–10 منٹ پکائیں یہاں تک کہ پک جائیں، لیکن ابھی کافی سخت رہیں۔ سارا مائع نکال دیں۔","مرچ ڈالیں اور موٹا موٹا مسل کر سب کچھ ملا دیں، اسپراؤٹس کے کچھ ٹکڑے مسلے ہوئے آمیزے میں رہنے دیں۔ ایک طرف رکھ دیں۔","دوسرے بڑے نان اسٹک پین میں درمیانی آنچ پر زیتون کا تیل ڈالیں، پھر پیاز ڈالیں۔ بار بار ہلاتے ہوئے 3-4 منٹ پکائیں۔","اب آلو اور اسپراؤٹس کا آمیزہ پین میں ڈالیں اور اچھی طرح ملائیں۔ اسے چپٹا کر دیں تاکہ پورا پین ڈھک جائے۔ 5 منٹ پکائیں اور بار بار الٹ پلٹ کریں تاکہ آمیزہ گڈمڈ ہو جائے، یہ عمل دو تین بار دہرائیں تاکہ کرکرا پرت بن جائے۔","اوپر ایک پچا ہوا انڈا رکھیں اور پیش کریں۔"],
["بچی ہوئی چیزوں کو استعمال کرنے کا بہترین طریقہ ہے، لہٰذا اگر آپ کے پاس ٹھنڈے آلو یا اسپراؤٹس ہوں تو بس چند منٹ گرم کریں اور مرحلہ 3 سے شروع کریں۔","دوسری سبزیاں جیسے گاجر، شلجم یا پارسنیپ بھی اچھی رہتی ہیں۔","'خطرے والے' گروہ جیسے شیر خوار، بچے، حاملہ خواتین، بزرگ اور بیمار افراد کو نرم/ہلکے پکے ہوئے اور کچے انڈوں سے پرہیز کرنا چاہیے، جب تک کہ وہ اس بات کی ضمانت نہ دے سکیں کہ وہ Lion کوالٹی ایشورنس اسکیم کے تحت تیار کیے گئے ہیں۔",FVH(2)],[]))
recs.append(R(7163244,"مائیکرو ویو مگ: سوئٹ کارن اور چیڈر بغیر پرت کا کیش","نمک میں کم مگر نمکین ذائقے سے بھرپور ایک مزیدار اسنیک، فوری رات کے کھانے یا بچے کی جلدی کی چائے کے لیے بہترین۔","1","172 گرام",
["1 انڈا، پھینٹا ہوا","2 کھانے کے چمچ 0% چکنائی والا یونانی طرز کا دہی","1 ڈھیر والا چائے کا چمچ کارن فلور","15 گرام آدھی چکنائی والا چیڈر، باریک کدوکش کیا ہوا","2 ہری پیاز، باریک کٹی ہوئی","40 گرام منجمد سوئٹ کارن، پگھلائی ہوئی","اچھی طرح پسی ہوئی کالی مرچ","آدھا چائے کا چمچ ریپ سیڈ کا تیل"],
["انڈے کو پیالے میں ڈالیں اور اس میں دہی، کارن فلور اور پنیر پھینٹ کر ملائیں۔ ہری پیاز اور سوئٹ کارن ملا دیں۔ ذرا سی کالی مرچ پیس کر ڈالیں۔","مگ پر ہلکا تیل لگائیں اور اجزاء ڈال دیں۔ پوری طاقت (800W) پر دو منٹ گرم کریں۔ پیش کرنے سے پہلے 1 منٹ رکھا رہنے دیں۔"],
["اسے براہ راست مگ سے کھایا جا سکتا ہے یا پلیٹ پر الٹ کر سلاد یا موسمی سبزیوں کے ساتھ پیش کیا جا سکتا ہے۔","مکئی کی جگہ منجمد مٹر بھی اچھے رہتے ہیں، یا دونوں کا ملاپ آزمائیں۔","اضافی ذائقے کے لیے کچھ تازہ تلسی، چائیوز، دھنیا یا اجمود ڈالیں۔",FVH(0)],[]))
recs.append(R(7165971,"بوئیابیس","بحیرہ روم کا بھرپور سمندری غذا کا سوپ، سبزیوں اور لہسن سے بھرا ہوا۔ ایک پیالے میں پیٹ بھرنے والا کھانا۔","4","500 گرام",
["1 شکر قندی، چھلی اور چوکور کٹی ہوئی (200 گرام)","1 گاجر، چھوٹی چوکور کٹی ہوئی (100 گرام)","1 مچھلی کا اسٹاک کیوب، 600 ملی لیٹر پانی میں گھلا ہوا","آدھا گانٹھ سونف، کٹی ہوئی (175 گرام)","1 پیلی شملہ مرچ، کٹی ہوئی (140 گرام)","1 لیک، کٹا ہوا (150 گرام)","ذرا سی چٹکی ہلدی (رنگ کے لیے، روایتی زعفران سے سستی)","اچھی خاصی چٹکی سفید مرچ","2 جوے لہسن، کُوٹے ہوئے","2 چائے کے چمچ سورج مکھی کا تیل","4 x بریم مچھلی کے فلے (90 گرام ہر ایک)، آدھے کٹے ہوئے تاکہ 8 ٹکڑے بنیں","150 گرام کا پیکٹ پکے ہوئے، چھلے ہوئے کنگ پرانز","150 گرام کا پیکٹ پکا ہوا، ٹھنڈا کیا ہوا مسلز کا گوشت","2 بڑے ٹماٹر، چھلکا اتارے ہوئے، بیج نکالے ہوئے اور چھوٹے کٹے ہوئے (100 گرام گودا)","1 کھانے کا چمچ باریک کٹا ہوا اجمود","اچھی طرح پسی ہوئی کالی مرچ"],
["شکر قندی اور گاجر کو اسٹاک کے ساتھ پین میں ڈالیں، ابال آنے دیں، پھر آنچ کم کریں، ڈھانپ دیں اور 7 منٹ دھیمی آنچ پر پکائیں۔","سونف، پیلی شملہ مرچ، لیک، ہلدی، سفید مرچ اور لہسن ڈالیں، ملائیں، پھر ڈھانپ کر مزید 5 منٹ دھیمی آنچ پر پکائیں۔","اسی دوران بڑے نان اسٹک فرائنگ پین میں درمیانی تیز آنچ پر 1 چائے کا چمچ تیل ڈالیں۔ جب پین گرم ہو جائے تو مچھلی کے 4 ٹکڑے، فلے کی جلد والی طرف نیچے رکھ کر 2-3 منٹ پکائیں۔ پلٹ دیں اور مزید 1-2 منٹ پکائیں۔ گرم پلیٹ پر رکھ دیں اور باقی مچھلی کے فلے ایک اور چائے کے چمچ تیل کے ساتھ پکائیں – اگر آپ کے پاس کافی بڑا پین ہو تو سب ایک ہی بار میں پکا سکتے ہیں۔","مسلز اور جھینگے سبزیوں اور اسٹاک میں ڈالیں، ابال آنے دیں اور 2 منٹ پکائیں۔","سبزیاں، جھینگے، مسلز اور شوربہ 4 پیالوں میں تقسیم کریں۔ مچھلی کے فلے اوپر رکھیں، اجمود، کٹے ہوئے ٹماٹر کا گودا اور تھوڑی سی کالی مرچ چھڑک کر پیش کریں۔"],
["بوئیابیس روایتی طور پر بچی ہوئی مچھلی سے بنایا جاتا تھا – جو بھی موسم میں ہو – لہٰذا تقریباً کوئی بھی مچھلی چلتی ہے۔","ٹماٹر چھیلنے کے لیے انہیں 1 منٹ کے لیے ابلتے پانی میں ڈبو دیں اور چھلکا آسانی سے اتر جائے گا۔",FVH(2)],[]))
recs.append(R(7176015,"کیل اور ہری مسور کا سوپ","ایک غذائیت بخش سوپ جو جلدی بن جاتا ہے اور بہت صحت بخش ہے۔","4","362 گرام",
["2 چائے کے چمچ سورج مکھی کا تیل","2 پیاز، باریک کٹی ہوئی","1 بڑی گاجر، چوکور کٹی ہوئی","1 ڈنٹھل اجوائن، کٹا ہوا","1-2 جوے لہسن، کُوٹے ہوئے","1 چائے کا چمچ پسا ہوا زیرہ","1 کھانے کا چمچ ٹماٹر کا پیوری","1 x 400 گرام ڈبہ ہری مسور پانی میں (پانی بھی ڈالیں)","200 گرام کاوولو نیرو (کالا کیل) یا گھنگھریالا کیل، کٹا ہوا (موٹے ڈنٹھل نکالے ہوئے)","500 ملی لیٹر سبزیوں کا اسٹاک","کالی مرچ، ذائقے کے مطابق"],
["پین کو درمیانی آنچ پر رکھ کر تیل ڈالیں، پیاز ڈالیں اور 7–10 منٹ ہلاتے رہیں یہاں تک کہ اچھی طرح بھوری ہو جائے۔","گاجر اور اجوائن ڈالیں اور بار بار ہلاتے ہوئے مزید 2–3 منٹ پکائیں۔","اب لہسن، زیرہ، ٹماٹر کا پیوری اور مسور ڈالیں اور اچھی طرح ملائیں۔","اسٹاک ڈالیں، ابال آنے دیں، آنچ کم کریں، ڈھانپ دیں اور 12 منٹ دھیمی آنچ پر پکائیں۔","کیل ڈالیں، ڈھکن واپس لگا دیں اور مزید 5 منٹ دھیمی آنچ پر پکائیں، کالی مرچ ڈالیں اور پیش کریں۔"],
["آپ کوئی بھی اسٹاک، جیسے مرغی یا گائے کا، استعمال کر سکتے ہیں۔ اسٹاک میں نمک زیادہ ہو سکتا ہے اس لیے جب بھی ممکن ہو کم نمک والے اختیارات منتخب کریں۔","ریشہ ریشہ کی ہوئی مرغی کی چھاتی یا میرینیٹ کیے ہوئے یا دھوئیں پر پکے ٹوفو کے ٹکڑے ڈال کر دیکھیں۔","آپ دوسری سبزیاں بھی ڈال سکتے ہیں، جیسے شملہ مرچیں، زوکینی، بروکلی یا ڈبے کی سوئٹ کارن۔","منجمد کرنے کی ہدایات: حصوں میں منجمد کریں، پھر فریج میں پگھلائیں، یا مائیکرو ویو میں پگھلائیں اور باقاعدگی سے ہلاتے رہیں۔",FVH(3)],[]))
recs.append(R(7176104,"روبارب فول","پکائے ہوئے روبارب کا میٹھا، مصنوعی سویٹنر سے میٹھا کیا ہوا اور کم چکنائی والے دہی اور کریم فریش میں ملایا ہوا۔","6","117 گرام",
["400 گرام روبارب، 1 سینٹی میٹر کے ٹکڑوں میں کٹا ہوا","مصنوعی سویٹنر، ذائقے کے مطابق (8 چائے کے چمچ چینی کے برابر، جیسے 8 اسٹیویا گولیاں، کُٹی ہوئی)","150 گرام 0% چکنائی والا یونانی دہی","100 گرام کم چکنائی والی کریم فریش"],
["روبارب کو 3 کھانے کے چمچ پانی کے ساتھ پین میں ڈالیں۔ ابال آنے دیں، آنچ کم کریں، ڈھکن لگائیں اور بار بار ہلاتے ہوئے 6 منٹ دھیمی آنچ پر پکائیں، اگر چپکنے لگے تو ایک اور کھانے کا چمچ پانی ڈال دیں۔ روبارب نرم ہونا چاہیے، لیکن اپنی شکل برقرار رکھے۔","روبارب کو پیالے میں منتقل کریں اور اگر استعمال کر رہے ہیں تو مصنوعی سویٹنر ڈال دیں۔ اچھی طرح ملائیں اور چکھیں، ضرورت ہو تو تھوڑا اور مصنوعی سویٹنر ڈالیں، پھر ٹھنڈا ہونے دیں۔ یاد رکھیں کہ پھل میں قدرتی شکر ہوتی ہے اس لیے زیادہ میٹھا نہ کریں۔","پیالے میں دہی اور کریم فریش ایک ساتھ ملائیں اور روبارب کو نرمی سے ملا دیں۔ گلاسوں میں ڈالیں اور پیش کرنے سے پہلے ٹھنڈا کریں۔"],
["پہلے سے بنا کر چند گھنٹوں کے لیے فریج میں رکھا جا سکتا ہے۔ یا اگر آپ اسے پیش کرنے سے ایک دن پہلے بنانا چاہتے ہیں تو روبارب کو الگ سے ٹھنڈا کریں اور ضرورت پر دہی اور کریم فریش کے ساتھ ملا لیں۔","یہ ترکیب دوسرے کھٹے پھلوں، جیسے گوزبیریز یا ریڈ کرنٹس، کے ساتھ اچھی بنتی ہے۔","آپ زیادہ تر پھل استعمال کر سکتے ہیں، البتہ اگر پھل میٹھا ہو تو اسے اتنا میٹھا کرنے کی ضرورت نہیں ہوگی۔ خوبانی، آڑو، نیکٹرین، رسبھری یا چیری آزمائیں۔","اس ترکیب میں 0% چکنائی والا دہی اور کم چکنائی والی کریم فریش استعمال ہوتی ہے، لیکن آپ اپنی پسند کا سادہ ورژن استعمال کر سکتے ہیں۔ البتہ اس سے ڈش کی غذائی معلومات اور بناوٹ بدل جائے گی۔","ویگن ورژن کے لیے بغیر میٹھے سویا یا ناریل پر مبنی دہی استعمال کریں۔"],[]))
recs.append(R(7177299,"ٹسکن پھلیوں کا سوپ","یہ بھرپور سوپ پیٹ بھرنے والا اور غذائیت بخش کھانا بناتا ہے، اور اسے آسانی سے اپنی پسندیدہ سبزیاں شامل کرنے کے لیے ڈھالا جا سکتا ہے۔","4","396 گرام",
["1 چائے کا چمچ زیتون کا تیل","1 پیاز، کٹی ہوئی","1 پیلی شملہ مرچ، کٹی ہوئی","1 گاجر، چوکور کٹی ہوئی","500 ملی لیٹر گلوٹین فری، کم نمک والا سبزیوں کا اسٹاک","400 گرام ڈبہ کٹے ہوئے ٹماٹر","2 پتا گوبھی کے پتے، کٹے ہوئے","1 ڈھیر والا چائے کا چمچ اوریگانو","آدھا چائے کا چمچ تھائم","400 گرام ڈبہ بورلوٹی پھلیاں، پانی نکالی ہوئی","2–4 جوے لہسن، کُوٹے ہوئے","2 چائے کے چمچ پیسٹو","پیش کرنے کے لیے کالی مرچ، پنیر کا ایک قتلہ اور تازہ تلسی کی ٹہنیاں"],
["پین میں تیل ڈالیں اور پیاز، شملہ مرچ اور گاجر ملا دیں۔ 5 منٹ بار بار ہلائیں یہاں تک کہ بھورا ہونے لگے۔","اسٹاک، ٹماٹر، پتا گوبھی، اوریگانو، تھائم، پھلیاں اور لہسن ڈالیں۔ ابال آنے دیں، پھر آنچ کم کریں، ڈھکن لگا دیں اور 10 منٹ دھیمی آنچ پر پکائیں۔","پیالوں میں ڈالیں، ہر ایک میں ایک ڈلی پیسٹو ڈالیں اور خوب کالی مرچ چھڑکیں۔ پیش کرتے وقت، اگر پسند ہو تو پنیر کا ایک قتلہ اور سجاوٹ کے لیے تازہ تلسی کی ایک ٹہنی ڈالیں۔"],
["بہت سی روایتی ترکیبوں کی طرح، یہ سوپ عموماً جو بھی دستیاب ہو اس سے بنایا جاتا ہے۔ آپ ہر طرح کی سبزیاں، جیسے کدو، زوکینی یا اجوائن، ڈال سکتے ہیں، یا مختلف پھلیاں، پاستا، یا حتیٰ کہ گوشت، جیسے ہیم، ڈال سکتے ہیں۔","بورلوٹی پھلیاں چکنائی میں کم، غذائی ریشے سے بھرپور اور پروٹین اور فولیٹ کا اچھا ذریعہ ہیں۔","تیز ذائقے والا پنیر، جیسے پارمیزان، گراں پادانو یا چیڈر، استعمال کرنے کا مطلب ہے کہ آپ اپنی پکوان میں اسے کم استعمال کر سکتے ہیں، پھر بھی بہترین ذائقے کا لطف اٹھا سکتے ہیں۔","منجمد کرنے کی ہدایات: حصوں میں منجمد کریں، پھر فریج میں پگھلائیں، یا مائیکرو ویو میں پگھلائیں اور باقاعدگی سے ہلاتے رہیں۔",FVH(3)],[]))
recs.append(R(7178593,"گلابی پچے ہوئے ناشپاتی","ناشپاتیاں چینی سے پاک بلیک کرنٹ کورڈیل میں پکائی گئیں، جس میں سٹار اینیس اور دار چینی کا مسالہ ہے۔","4","312 گرام",
["4 سخت، ذرا کچے ناشپاتیاں، چھلی ہوئی اور ڈنٹھل لگا رہنے دیا گیا","150 ملی لیٹر چینی سے پاک بلیک کرنٹ کورڈیل","500-600 ملی لیٹر ابلتا پانی (ناشپاتیوں کو ڈھانپنے کے لیے کافی)","2 سٹار اینیس","1 دار چینی کی چھڑی"],
["ناشپاتیاں چھیل لیں اور چھوٹے چاقو یا سبزی چھیلنے والے سے نیچے کی طرف سے گودا نکال دیں۔ نیچے کا حصہ سیدھا کاٹ دیں تاکہ ناشپاتیاں کھڑی رہ سکیں۔","ناشپاتیاں پین میں 3:1 کے تناسب سے پتلے کیے ہوئے کورڈیل کے ساتھ ڈالیں، اس بات کو یقینی بنائیں کہ وہ پوری طرح ڈوبی ہوئی ہوں۔","سٹار اینیس اور دار چینی کی چھڑی ڈالیں، پھر ابال آنے دیں۔ آنچ کم کریں اور 20-30 منٹ دھیمی آنچ پر پکائیں یہاں تک کہ ناشپاتیاں نرم ہو جائیں۔","پین سے نکال کر ایک طرف رکھ دیں۔ مائع کو 10-15 منٹ ابالیں یہاں تک کہ کم ہو کر تقریباً 200 ملی لیٹر رہ جائے، پھر سٹار اینیس اور دار چینی کی چھڑی نکال دیں۔","ناشپاتیاں پیش کرنے والی ڈش پر رکھیں اور اوپر ساس ڈال دیں۔ ایک چمچ کم چکنائی والے دہی یا غیر دودھ والے متبادل کے ساتھ پیش کریں۔"],
["ناشپاتیوں کی جگہ سیب کے ساتھ بھی بہت اچھا بنتا ہے۔","مختلف کورڈیل استعمال کرنے کی کوشش کریں یا تازہ ادرک کے چند قتلے یا 2 لونگ ڈالیں۔",FVH(1)],[]))
recs.append(R(7179097,"کھمبی پسندا","یہ مزیدار سبزی خور سالن مختلف مسالوں کو یکجا کر کے ایک ذائقہ دار گریوی بناتا ہے جو شاہ بلوط کھمبیوں کے ساتھ بالکل ٹھیک بیٹھتی ہے۔ یہ ترکیب Slimming World کے اشتراک سے منتخب کی گئی تھی۔","4","646 گرام",
["کم کیلوری والا کوکنگ اسپرے","1 پیاز، باریک کٹی ہوئی","4 جوے لہسن، کُوٹے ہوئے","3 سینٹی میٹر کا ٹکڑا تازہ ادرک کی جڑ، چھلی اور کدوکش کی ہوئی","1 ہری مرچ، باریک کٹی ہوئی، اگر چاہیں تو بیج نکال دیں","2 چائے کے چمچ زیرہ","1 چائے کا چمچ دھنیا کے بیج","½ چائے کا چمچ پسی ہوئی میتھی","½ چائے کا چمچ پسی ہوئی ہلدی","1 چائے کا چمچ خشک گرم مسالہ","½ چائے کا چمچ ہلکی لال مرچ کا پاؤڈر (اختیاری)","400 گرام ڈبے کے ٹماٹر","400 ملی لیٹر سادہ بغیر میٹھا بادام کا مشروب","1 کلو شاہ بلوط کھمبیاں، اگر بڑی ہوں تو آدھی کٹی ہوئی","چٹکی بھر زعفران کے ریشے، 1 کھانے کے چمچ ابلتے پانی میں بھگوئے ہوئے","1 خشک تیز پات","1 دار چینی کی چھڑی","4 کھانے کے چمچ چکنائی سے پاک بغیر میٹھا سادہ دہی، پیش کرنے کے لیے","20 گرام تازہ دھنیا کے پتے، پیش کرنے کے لیے"]+G("پلاؤ چاول کے لیے",["200 گرام خشک باسمتی چاول","1 دار چینی کی چھڑی","4 کُوٹی ہوئی ہری الائچیاں","3 لونگ","چٹکی بھر زعفران کے ریشے"]),
["بڑے، گہرے، نان اسٹک فرائنگ پین پر کم کیلوری والے کوکنگ اسپرے کے دو تین پمپ کریں اور درمیانی آنچ پر رکھیں۔ پیاز کو 5 منٹ بھونیں یہاں تک کہ نرم ہو جائے۔ لہسن، ادرک اور ہری مرچ کو تھوڑے پانی کے ساتھ ڈالیں، پھر 3 منٹ بھونیں۔ مسالے اور تھوڑا پانی ڈالیں اور 2 منٹ بھونیں۔","ٹماٹر اور بادام کا مشروب پین میں ڈالیں اور سب کو ابال پر لے آئیں۔ بار بار ہلاتے ہوئے 8-10 منٹ آہستہ سے ابالیں، یا جب تک ٹماٹر گل نہ جائیں۔","200 گرام خشک باسمتی چاول ڈھکن والے نان اسٹک سوس پین میں 1 دار چینی کی چھڑی، الائچیاں، لونگ اور زعفران کے ساتھ ڈالیں۔ اتنا پانی ڈالیں کہ چاولوں سے ناخن کی اونچائی کے برابر اوپر آ جائے اور درمیانی تیز آنچ پر رکھیں۔ ابال آنے دیں، 1 منٹ ابالیں اور ڈھانپ دیں۔ آنچ کو جتنی کم ہو سکے کم کر دیں اور ڈھکن ہٹائے بغیر 20 منٹ پکائیں، یا جب تک سارا مائع جذب نہ ہو جائے۔","ٹماٹر کا آمیزہ ایک بڑے ناپنے والے جگ میں منتقل کریں، پھر اسٹک بلینڈر سے ہموار ساس میں پیس لیں۔ ساس کو پین میں رکھنے کی بجائے جگ میں منتقل کرنے سے بلینڈر کو اسے زیادہ ہموار پیسنے میں مدد ملتی ہے۔ (آپ جگ بلینڈر بھی استعمال کر سکتے ہیں۔) ایک طرف رکھ دیں۔","بڑے نان اسٹک فرائنگ پین پر کم کیلوری والے کوکنگ اسپرے کے دو تین پمپ کریں اور درمیانی تیز آنچ پر رکھیں۔ جب گرم ہو جائے تو آدھی کھمبیاں ڈالیں اور کبھی کبھار ہلاتے ہوئے 5-6 منٹ بھونیں، یہاں تک کہ وہ گہری سنہری بھوری ہو جائیں۔ پلیٹ پر منتقل کریں اور باقی کھمبیوں کے ساتھ دہرائیں۔","ساس کو پین میں واپس ڈالیں۔ زعفران، تیز پات اور دار چینی ڈالیں اور ابال پر لے آئیں۔ کھمبیاں ڈالیں اور بار بار ہلاتے ہوئے 8-10 منٹ دھیمی آنچ پر پکائیں۔ کالی مرچ ڈالیں۔ 4 پیالوں میں تقسیم کریں، تیز پات اور دار چینی نکال دیں۔ اوپر دہی اور دھنیا ڈالیں۔","بہترین نتائج کے لیے چاولوں کو کانٹے سے ہلکا کریں، پیش کرتے وقت دار چینی، الائچیاں اور لونگ نکال دیں۔"],
["فائبر بڑھانے کے لیے براؤن باسمتی چاول استعمال کریں۔","مسالے/سیزننگ کے آمیزوں میں چینی، نمک، آٹا یا تیل جیسے اضافی اجزاء کی جانچ کریں۔ اگر ممکن ہو تو صرف جڑی بوٹیوں اور مسالوں سے بنے آمیزے منتخب کریں۔","آپ اپنی پسند کا سادہ دہی استعمال کر سکتے ہیں۔ البتہ اس سے ڈش کی غذائی معلومات اور بناوٹ بدل جائے گی۔",FVH(4)],[]))
